-- Several menus per venue, exactly one live (D88, D90, D91, D92; adjustments M1; T79).
-- Generated by drizzle-kit, then edited by hand: the unique rule moved before the foreign key that
-- needs it, the backfill of `venues.live_menu_id`, the `updated_at` trigger. One transaction:
--   0. `venues` stops forcing row-level security on its owner for the length of this transaction
--      and stops touching `updated_at` (same reasons as 0015 and 0018): the backfill must see every
--      row and change nothing else;
--   1. `menus`: the one-per-venue rule goes; a header name, an order key, settings and a bin mark
--      (`deleted_at`) come; `updated_at` with its trigger. Existing menus keep their place with the
--      first order key, `a0`;
--   2. `venues.live_menu_id` points at the venue's one menu of today (every venue with a menu is
--      backfilled; a venue without one stays null until core gives it a menu) and
--      `unpublished_at` for Unpublish (D86). Purging the live menu clears the pointer, and only
--      the pointer: the foreign key is written by hand as ON DELETE SET NULL (live_menu_id),
--      because a plain SET NULL on a composite key would null `tenant_id` and `id` too (the
--      Drizzle schema cannot say the column list; it states the plain form, which is what
--      drizzle-kit compares against). So the purge job needs no UPDATE on `venues`;
--   3. back to normal.
-- Privileges: the app role gains UPDATE on `menus` (src/table-access.ts; `pnpm db:roles`); a
-- trigger keeps a menu's venue, template and root node pinned once, as the missing UPDATE did.

-- 0. Owner access for the backfill; undone at step 3.
ALTER TABLE "restro"."venues" NO FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "restro"."venues" DISABLE TRIGGER "venues_touch_updated_at";--> statement-breakpoint

-- 1. Menus: many per venue, named, ordered, binnable.
ALTER TABLE "restro"."menus" DROP CONSTRAINT "menus_venue_id_unique";--> statement-breakpoint
ALTER TABLE "restro"."menus" ADD COLUMN "name" text;--> statement-breakpoint
ALTER TABLE "restro"."menus" ADD COLUMN "sort_key" text COLLATE "C" DEFAULT 'a0' NOT NULL;--> statement-breakpoint
ALTER TABLE "restro"."menus" ADD COLUMN "settings" jsonb DEFAULT '{}'::jsonb NOT NULL;--> statement-breakpoint
ALTER TABLE "restro"."menus" ADD COLUMN "deleted_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "restro"."menus" ADD COLUMN "updated_at" timestamp with time zone DEFAULT now() NOT NULL;--> statement-breakpoint
CREATE INDEX "menus_venue_id_idx" ON "restro"."menus" USING btree ("venue_id","sort_key");--> statement-breakpoint
ALTER TABLE "restro"."menus" ADD CONSTRAINT "menus_tenant_id_venue_id_id_unique" UNIQUE("tenant_id","venue_id","id");--> statement-breakpoint
ALTER TABLE "restro"."menus" ADD CONSTRAINT "menus_name_length" CHECK ("restro"."menus"."name" is null or (char_length("restro"."menus"."name") between 1 and 120 and "restro"."menus"."name" = btrim("restro"."menus"."name")));--> statement-breakpoint
ALTER TABLE "restro"."menus" ADD CONSTRAINT "menus_sort_key_format" CHECK ("restro"."menus"."sort_key" ~ '^[A-Za-z][0-9A-Za-z]*$');--> statement-breakpoint
ALTER TABLE "restro"."menus" ADD CONSTRAINT "menus_settings_object" CHECK (jsonb_typeof("restro"."menus"."settings") = 'object');--> statement-breakpoint
CREATE TRIGGER menus_touch_updated_at BEFORE UPDATE ON restro.menus
  FOR EACH ROW EXECUTE FUNCTION restro.touch_updated_at();--> statement-breakpoint
-- A menu's venue, template and root node (and its ids) are pinned when it is created: with the
-- app role now updating menus (name, order, settings, the bin), the trigger keeps that promise.
CREATE FUNCTION restro.menus_guard_update()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog
AS $$
BEGIN
  IF (NEW.id, NEW.tenant_id, NEW.venue_id, NEW.template_key, NEW.template_version,
      NEW.root_node_id, NEW.created_at)
     IS DISTINCT FROM
     (OLD.id, OLD.tenant_id, OLD.venue_id, OLD.template_key, OLD.template_version,
      OLD.root_node_id, OLD.created_at) THEN
    RAISE EXCEPTION 'menus_guard_update: a menu''s venue, template and root node are pinned once; only its name, order, settings and bin mark change'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;--> statement-breakpoint
REVOKE ALL ON FUNCTION restro.menus_guard_update() FROM PUBLIC;--> statement-breakpoint
CREATE TRIGGER menus_guard_update BEFORE UPDATE ON restro.menus
  FOR EACH ROW EXECUTE FUNCTION restro.menus_guard_update();--> statement-breakpoint

-- 2. The venue's live menu and the Unpublish mark.
ALTER TABLE "restro"."venues" ADD COLUMN "live_menu_id" text;--> statement-breakpoint
ALTER TABLE "restro"."venues" ADD COLUMN "unpublished_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "restro"."venues" ADD CONSTRAINT "venues_live_menu_fk" FOREIGN KEY ("tenant_id","id","live_menu_id") REFERENCES "restro"."menus"("tenant_id","venue_id","id") ON DELETE SET NULL ("live_menu_id") ON UPDATE no action;--> statement-breakpoint
UPDATE "restro"."venues" v
SET "live_menu_id" = m."id"
FROM "restro"."menus" m
WHERE m."tenant_id" = v."tenant_id" AND m."venue_id" = v."id" AND v."live_menu_id" IS NULL;--> statement-breakpoint
DO $$
DECLARE
  unlinked bigint;
BEGIN
  SELECT count(*) INTO unlinked
  FROM restro.venues v
  WHERE v.live_menu_id IS NULL
    AND EXISTS (SELECT 1 FROM restro.menus m WHERE m.tenant_id = v.tenant_id AND m.venue_id = v.id);
  IF unlinked > 0 THEN
    RAISE EXCEPTION '0019_menus_many: % venues with a menu have no live menu; the migration owner must be able to update restro.venues (superuser, BYPASSRLS, or the table owner)', unlinked;
  END IF;
END
$$;--> statement-breakpoint

-- 3. Back to normal.
ALTER TABLE "restro"."venues" ENABLE TRIGGER "venues_touch_updated_at";--> statement-breakpoint
ALTER TABLE "restro"."venues" FORCE ROW LEVEL SECURITY;
